package com.example.rokidgeminisecretary;
import android.app.*;import android.location.Address;import android.widget.*;import java.util.*;
/** User-confirmed one-stop destination; no route starts from candidate selection. */
final class NavigationStopoverDialog {
 interface Selection{void use(String label,Address address);}
 static void show(Activity host,String destination,Selection selected){
  LinearLayout body=new LinearLayout(host);body.setPadding(24,16,24,12);body.setOrientation(1);TextView hint=new TextView(host);hint.setText("立ち寄る施設・お店を検索します。住所・座標を確認して選んでください。経路を開始する前に立ち寄りを設定し、最終目的地を暗号化して保持します。");body.addView(hint);EditText query=new EditText(host);query.setSingleLine(true);query.setHint("例：立川駅近くのコンビニ");query.setText(destination);body.addView(query);TextView status=new TextView(host);body.addView(status);
  AlertDialog dialog=new AlertDialog.Builder(host).setTitle("立ち寄る場所").setView(body).setPositiveButton("立ち寄り先を検索",null).setNegativeButton("閉じる",null).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{String text=query.getText().toString().trim();if(text.isEmpty()||text.length()>160){status.setText("立ち寄り先の名前を160文字以内で入力してください");return;}dialog.getButton(-1).setEnabled(false);status.setText("候補を取得中…");new Thread(()->{try{java.util.List<Address> choices=GoogleNavigationClient.enabled(host)?GoogleNavigationClient.searchPlaces(host,text):new android.location.Geocoder(host,Locale.JAPAN).getFromLocationName(text,5);host.runOnUiThread(()->{if(!dialog.isShowing()||host.isDestroyed())return;dialog.getButton(-1).setEnabled(true);if(choices==null||choices.isEmpty()){status.setText("候補がありません。入口の名前・地域を確認してください。別の場所へ自動で置き換えません。");return;}List<Address> valid=new ArrayList<>();List<String> names=new ArrayList<>();for(Address a:choices)if(a.hasLatitude()&&a.hasLongitude()&&Double.isFinite(a.getLatitude())&&Double.isFinite(a.getLongitude())&&Math.abs(a.getLatitude())<=90&&Math.abs(a.getLongitude())<=180){valid.add(a);names.add((a.getAddressLine(0)==null?text:a.getAddressLine(0))+"\n"+a.getLatitude()+", "+a.getLongitude());}if(valid.isEmpty()){status.setText("座標を確認できる入口候補がありません");return;}new AlertDialog.Builder(host).setTitle("立ち寄り先の候補を確認").setItems(names.toArray(new String[0]),(d,i)->new AlertDialog.Builder(host).setTitle("この地点を立ち寄り先として使う").setMessage(names.get(i)+"\n住所・座標を確認してください。選択後に経路開始の確認へ進みます。").setPositiveButton("目的地に設定",(confirm,w)->{if(!dialog.isShowing())return;selected.use(text+" / "+names.get(i).split("\\n")[0],valid.get(i));dialog.dismiss();}).setNegativeButton("戻る",null).show()).setNegativeButton("戻る",null).show();});}catch(Exception e){host.runOnUiThread(()->{if(dialog.isShowing()){dialog.getButton(-1).setEnabled(true);status.setText("候補を取得できません。通信・検索設定を確認してください");}});}},"LokiStopoverSearch").start();});
 }
 private NavigationStopoverDialog(){}
}
